def test_invalid_kind_and_empty_fields_rejected(self) -> None:
    obj = json.loads(self.good())
    without = dict(obj["records"][0])
    without["kind"] = "bogus"
    digest_input = {k: without[k] for k in ("detail", "kind", "prev", "seq", "source")}
    obj["records"][0]["kind"] = "bogus"
    obj["records"][0]["hash"] = __import__("hashlib").sha256(
        canonical(digest_input)
    ).hexdigest()
    self.reject(canonical(obj) + b"\n")

